#requires -Version 5.1
[CmdletBinding()]
param(
    [string]$PublicUrl,
    [string]$LocalUrl,
    [Parameter(Mandatory = $true)][ValidateRange(1, 65535)][int]$MetricsPort,
    [ValidateRange(1, 1440)][int]$Minutes = 60,
    [ValidateRange(5, 300)][int]$IntervalSeconds = 15,
    [ValidateRange(0, 3600)][int]$MaximumAllowedOutageSeconds = 0,
    [string]$OutputPath,
    [switch]$AllowUrlArguments,
    [switch]$TestMode
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$curl = (Get-Command curl.exe -ErrorAction Stop).Source
Import-Module (Join-Path (Split-Path $PSScriptRoot -Parent) 'scripts\WorkspaceShare.Health.psm1') -Force -ErrorAction Stop
Import-Module (Join-Path (Split-Path $PSScriptRoot -Parent) 'scripts\WorkspaceShare.Curl.psm1') -Force -ErrorAction Stop
if($AllowUrlArguments -and -not $TestMode){[Console]::Error.WriteLine('-AllowUrlArguments is permitted only with -TestMode.');exit 2}
if(($PSBoundParameters.ContainsKey('PublicUrl') -or $PSBoundParameters.ContainsKey('LocalUrl')) -and -not $AllowUrlArguments){[Console]::Error.WriteLine('URL arguments are disabled because process command lines are observable. Use secret prompts or process environment variables.');exit 2}
$script:SoakSecretTokens=@()

function Read-SecretString {
    param([Parameter(Mandatory = $true)][string]$Prompt)
    $secure = Read-Host $Prompt -AsSecureString; $pointer = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
    try { return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($pointer) } finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($pointer) }
}
function Invoke-Probe {
    param([Parameter(Mandatory = $true)][string]$Url,[int]$TimeoutSeconds=12,[int64]$Start=0,[int]$ExpectedBytes=0,[switch]$AllowFullFileResponse,[switch]$ReadTextBody)
    $id=[Guid]::NewGuid().ToString('N'); $root=[IO.Path]::GetTempPath(); $body=Join-Path $root "ws-soak-body-$id.tmp"; $headers=Join-Path $root "ws-soak-headers-$id.tmp"; $errors=Join-Path $root "ws-soak-error-$id.tmp"
    try {
        $end=$Start+[Math]::Max(0,$ExpectedBytes-1); $args=@('--silent','--show-error','--stderr',$errors,'--output',$body,'--dump-header',$headers,'--max-time',[string]$TimeoutSeconds,'--max-filesize','65536','--write-out','%{http_code}|%{remote_ip}|%{time_total}')
        if($ExpectedBytes -gt 0){$args+=@('--range',("{0}-{1}" -f $Start,$end))}; $result=WorkspaceShare.Curl\Invoke-CurlWithPrivateUrl -CurlPath $curl -Url $Url -Arguments $args -ProcessTimeoutSeconds ($TimeoutSeconds + 10); $parts=@($result.StdOut.Trim().Split('|'))
        $status=0; if($parts.Count -gt 0){[void][int]::TryParse($parts[0],[ref]$status)}; $remoteIp=if($parts.Count -gt 1){$parts[1]}else{''}; $seconds=0.0; if($parts.Count -gt 2){[void][double]::TryParse($parts[2],[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$seconds)}
        $actual=if(Test-Path -LiteralPath $body){[int](Get-Item -LiteralPath $body).Length}else{0}; $sha=if($actual -gt 0){(Get-FileHash -LiteralPath $body -Algorithm SHA256).Hash}else{''}; $headerText=if(Test-Path -LiteralPath $headers){[string](Get-Content -LiteralPath $headers -Raw)}else{''}; $errorText=if(Test-Path -LiteralPath $errors){[string](Get-Content -LiteralPath $errors -Raw)}else{''}; if($result.StdErr){$errorText+=[Environment]::NewLine+$result.StdErr}; $bodyText=if(($ReadTextBody -or $status -ge 400) -and (Test-Path -LiteralPath $body)){[string](Get-Content -LiteralPath $body -Raw)}else{''}
        $contentRange=''; $match=[regex]::Match($headerText,'(?im)^Content-Range:\s*([^\r\n]+)'); if($match.Success){$contentRange=$match.Groups[1].Value.Trim()}; $totalBytes=[int64]0; $totalMatch=[regex]::Match($contentRange,'/(\d+)$'); if($totalMatch.Success){[void][int64]::TryParse($totalMatch.Groups[1].Value,[Globalization.NumberStyles]::Integer,[Globalization.CultureInfo]::InvariantCulture,[ref]$totalBytes)}elseif($status -eq 200){$totalBytes=[int64]$actual}
        $retry=0; $retryMatch=[regex]::Match($headerText,'(?im)^Retry-After:\s*([^\r\n]+)'); if($retryMatch.Success){$retryValue=$retryMatch.Groups[1].Value.Trim();if(-not[int]::TryParse($retryValue,[ref]$retry)){$retryDate=[DateTime]::MinValue;if([DateTime]::TryParseExact($retryValue,'r',[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::AssumeUniversal,[ref]$retryDate)){$retry=[int][Math]::Max(0,[Math]::Ceiling(($retryDate.ToUniversalTime()-[DateTime]::UtcNow).TotalSeconds))}}}; $cf=0; $cfMatch=[regex]::Match($bodyText,'(?i)(?:"code"\s*:\s*|\berror\s+)(10\d{2})|\b(1033)\b'); if($cfMatch.Success){[void][int]::TryParse(($cfMatch.Groups[1].Value+$cfMatch.Groups[2].Value),[ref]$cf)}
        $valid=if($ExpectedBytes -gt 0){$rangeValid=($status -eq 206 -and $contentRange -match ('^bytes\s+{0}-{1}/' -f $Start,$end)); if($AllowFullFileResponse){$rangeValid=$rangeValid -or ($status -eq 200 -and $Start -eq 0)}; $result.ExitCode -eq 0 -and $rangeValid -and $actual -eq $ExpectedBytes}else{$result.ExitCode -eq 0 -and $status -in @(200,206)}
        return [pscustomobject]@{Exit=$result.ExitCode;Status=$status;RemoteIp=$remoteIp;Seconds=$seconds;Error=(WorkspaceShare.Curl\Protect-DiagnosticText $errorText @($PublicUrl,$LocalUrl) $script:SoakSecretTokens);CloudflareError=$cf;RetryAfter=$retry;ActualBytes=$actual;TotalBytes=$totalBytes;Sha256=$sha;SampleValid=$valid;Body=(WorkspaceShare.Curl\Protect-DiagnosticText $bodyText @($PublicUrl,$LocalUrl) $script:SoakSecretTokens)}
    } finally { Remove-Item -LiteralPath $body,$headers,$errors -Force -ErrorAction SilentlyContinue }
}
function Get-QuickTunnelHostnameState {
    param([int]$Port,[string]$ExpectedHostname)
    $path=Join-Path ([IO.Path]::GetTempPath()) ("ws-soak-quick-{0}.json" -f [Guid]::NewGuid().ToString('N'))
    try {$result=WorkspaceShare.Curl\Invoke-CurlWithPrivateUrl -CurlPath $curl -Url "http://127.0.0.1:$Port/quicktunnel" -Arguments @('--silent','--show-error','--max-time','5','--max-filesize','65536','--output',$path) -ProcessTimeoutSeconds 15; if($result.ExitCode -ne 0 -or -not(Test-Path $path)){return [pscustomobject]@{Available=$false;Matches=$false}}; $actual=([string]((Get-Content $path -Raw|ConvertFrom-Json).hostname)).Trim().ToLowerInvariant(); return [pscustomobject]@{Available=-not [string]::IsNullOrWhiteSpace($actual);Matches=($actual -eq $ExpectedHostname.Trim().ToLowerInvariant())}}catch{return [pscustomobject]@{Available=$false;Matches=$false}}finally{Remove-Item $path -Force -ErrorAction SilentlyContinue}
}

if([string]::IsNullOrWhiteSpace($PublicUrl)){$PublicUrl=[Environment]::GetEnvironmentVariable('WORKSPACESHARE_PUBLIC_URL','Process')}; if([string]::IsNullOrWhiteSpace($LocalUrl)){$LocalUrl=[Environment]::GetEnvironmentVariable('WORKSPACESHARE_LOCAL_URL','Process')}; [Environment]::SetEnvironmentVariable('WORKSPACESHARE_PUBLIC_URL',$null,'Process');[Environment]::SetEnvironmentVariable('WORKSPACESHARE_LOCAL_URL',$null,'Process');if([string]::IsNullOrWhiteSpace($PublicUrl)){$PublicUrl=Read-SecretString 'Paste the public WorkspaceShare URL'}; if([string]::IsNullOrWhiteSpace($LocalUrl)){$LocalUrl=Read-SecretString 'Paste the local WorkspaceShare URL'}; if([string]::IsNullOrWhiteSpace($OutputPath)){$OutputPath=Join-Path $PWD ('tunnel-soak-{0}.jsonl' -f [DateTime]::UtcNow.ToString('yyyyMMdd-HHmmss'))}
$publicUri=$null;$localUri=$null;if(-not[Uri]::TryCreate($PublicUrl,[UriKind]::Absolute,[ref]$publicUri) -or $publicUri.Scheme -ne 'https' -or $publicUri.DnsSafeHost -notmatch '^[a-z0-9-]+\.trycloudflare\.com$' -or -not $publicUri.IsDefaultPort -or $publicUri.UserInfo -or $publicUri.Query -or $publicUri.Fragment){[Console]::Error.WriteLine('Invalid public WorkspaceShare URL.');exit 2};if(-not[Uri]::TryCreate($LocalUrl,[UriKind]::Absolute,[ref]$localUri) -or $localUri.Scheme -ne 'http' -or $localUri.DnsSafeHost -ne '127.0.0.1' -or $localUri.UserInfo -or $localUri.Query -or $localUri.Fragment){[Console]::Error.WriteLine('Invalid local WorkspaceShare URL.');exit 2};$publicToken=[regex]::Match($publicUri.AbsolutePath,'^/d/([A-Za-z0-9_-]{43})/$');$localToken=[regex]::Match($localUri.AbsolutePath,'^/d/([A-Za-z0-9_-]{43})/$');if(-not$publicToken.Success -or -not$localToken.Success -or $publicToken.Groups[1].Value -cne $localToken.Groups[1].Value){[Console]::Error.WriteLine('Public and local URLs must contain the same capability token.');exit 2};$script:SoakSecretTokens=@($publicToken.Groups[1].Value)
$hostname=$publicUri.DnsSafeHost; $discovery=Invoke-Probe -Url $LocalUrl -TimeoutSeconds 5 -Start 0 -ExpectedBytes 1 -AllowFullFileResponse; if(-not $discovery.SampleValid -or $discovery.TotalBytes -le 0){[Console]::Error.WriteLine('Could not determine a valid local archive size.');exit 2}; $archiveSize=[int64]$discovery.TotalBytes; $samples=@(Get-HealthSamplePlan -ArchiveSize $archiveSize); $timer=[Diagnostics.Stopwatch]::StartNew();$durationSeconds=$Minutes*60.0;$lastSeconds=0.0; $iteration=0; $failedSamples=0; $currentOutageStartedSeconds=$null; $longestOutageSeconds=0.0
Write-Host "Soak test: <redacted>.trycloudflare.com for $Minutes minute(s); output: $OutputPath"
while($timer.Elapsed.TotalSeconds -lt $durationSeconds){$iteration++;$now=[DateTime]::UtcNow;$startedSeconds=$timer.Elapsed.TotalSeconds;$gap=$startedSeconds-$lastSeconds;$lastSeconds=$startedSeconds;$sample=$samples[($iteration-1)%$samples.Count];$evaluated=$false;try{$local=Invoke-Probe $LocalUrl 5 $sample.Start $sample.Length -AllowFullFileResponse:$sample.AllowFullFileResponse;$ready=Invoke-Probe "http://127.0.0.1:$MetricsPort/ready" 5 -ReadTextBody;$public=Invoke-Probe $PublicUrl 12 $sample.Start $sample.Length -AllowFullFileResponse:$sample.AllowFullFileResponse;$hostnameState=Get-QuickTunnelHostnameState $MetricsPort $hostname;$completedUtc=[DateTime]::UtcNow;$completedSeconds=$timer.Elapsed.TotalSeconds;$readyConnections=0;try{$readyConnections=[int](($ready.Body|ConvertFrom-Json).readyConnections)}catch{};$healthy=$local.SampleValid -and $public.SampleValid -and $local.Sha256 -eq $public.Sha256 -and $ready.Status -eq 200 -and $readyConnections -gt 0 -and $hostnameState.Available -and $hostnameState.Matches;if($healthy){if($null -ne $currentOutageStartedSeconds){$longestOutageSeconds=[Math]::Max($longestOutageSeconds,$completedSeconds-$currentOutageStartedSeconds);$currentOutageStartedSeconds=$null}}else{$failedSamples++;if($null -eq $currentOutageStartedSeconds){$currentOutageStartedSeconds=$startedSeconds}};$evaluated=$true;[ordered]@{utc=$completedUtc.ToString('o');iteration=$iteration;loopGapSeconds=[Math]::Round($gap,3);tunnelHost='<redacted>.trycloudflare.com';sampleStart=$sample.Start;sampleLength=$sample.Length;localSampleValid=$local.SampleValid;localStatus=$local.Status;readySuccess=($ready.Status -eq 200);readyConnections=$readyConnections;quickTunnelHostnameAvailable=$hostnameState.Available;quickTunnelHostnameMatches=$hostnameState.Matches;publicSampleValid=$public.SampleValid;publicExit=$public.Exit;publicStatus=$public.Status;cloudflareError=$public.CloudflareError;retryAfter=$public.RetryAfter;remoteIp=$public.RemoteIp;publicSeconds=$public.Seconds;publicError=$public.Error}|ConvertTo-Json -Compress|Add-Content $OutputPath -Encoding UTF8;Write-Host ("[{0}] {1} local={2}/{3} ready={4}/{5} public={6}/{7}/cf{8} gap={9:N0}s" -f $completedUtc.ToLocalTime().ToString('HH:mm:ss'),$(if($healthy){'HEALTHY'}else{'FAILED'}),$local.SampleValid,$local.Status,$ready.Status,$readyConnections,$public.SampleValid,$public.Status,$public.CloudflareError,$gap);}catch{if(-not $evaluated){$failedSamples++;if($null -eq $currentOutageStartedSeconds){$currentOutageStartedSeconds=$startedSeconds}};Write-Warning ('Sample-Fehler: ' + (WorkspaceShare.Curl\Protect-DiagnosticText $_.Exception.Message @($PublicUrl,$LocalUrl) $script:SoakSecretTokens))};$sleep=[Math]::Min($IntervalSeconds,[Math]::Max(0,$durationSeconds-$timer.Elapsed.TotalSeconds));if($sleep -gt 0){Start-Sleep -Milliseconds ([int]($sleep*1000))}}
if($null -ne $currentOutageStartedSeconds){$longestOutageSeconds=[Math]::Max($longestOutageSeconds,$timer.Elapsed.TotalSeconds-$currentOutageStartedSeconds)};Write-Host ("Samples: {0}; failed: {1}; longest outage: {2:N0}s" -f $iteration,$failedSamples,$longestOutageSeconds);$failed=if($MaximumAllowedOutageSeconds -eq 0){$failedSamples -gt 0}else{$longestOutageSeconds -gt $MaximumAllowedOutageSeconds};if($failed){exit 1};exit 0
